def nm(gs):
    cols=[]
    for i in [-2,-1,0,1]:
        for g in gs: cols.append(e**i*g)
    A=np.column_stack(cols); c=np.linalg.lstsq(A,s,rcond=None)[0]
    return np.mean((s-A@c)**2)/np.var(s)
